return async (path: string, init: RequestInit): Promise<Response> => {
  posted.push({ path, body: JSON.parse(String(init.body)) })
  const tool = Object.keys(answers).find(each => path.endsWith(each))
  if (!tool) throw new TypeError('fetch failed')
  return new Response(JSON.stringify(answers[tool]), { status: 200, headers: { 'content-type': 'application/json' } })
}

if (kind === 'story') return StoryClientGenerated.named(this.api, node)
if (kind === 'scenario') return ScenarioClientGenerated.named(this.api, node)
if (kind === 'step') return StepClientGenerated.named(this.api, node)
if (kind === 'increment') return IncrementClientGenerated.named(this.api, node)
return EpicClientGenerated.named(this.api, node)

const without = (nodes: string[], node: string) => nodes.filter(each => each !== node).join('\n')
const moved = after.find((node, index) => node !== before[index] && without(before, node) === without(after, node))
if (!moved) return this
const next = after[after.indexOf(moved) + 1]
if (next) return this.moveBeforeNode(moved, kind, next)
let answered: this | null = this
for (const passed of before.slice(before.indexOf(moved) + 1)) answered = await this.moveBeforeNode(passed, kind, moved)
return answered

return steps.flatMap(step => [step, ...step.ands]).map((step, index) => {
  const keyword = step.keyword.toLowerCase() as StepKeyword
  return { id: step.node, parent_id: scenario, step_type: KEYWORDS.includes(keyword) ? keyword : 'given', text: step.text, sequential_order: index + 1 }
})

const under = placesUnder(story.node)
const scenarios = story.scenarios.map((scenario, index) => ScenarioViewModel.of(scenario, under(index)))
return new StoryViewModel(story, place, story.story_type, scenarios, story.acceptance_tests)

const under = placesUnder(epic.node)
const own = epic.stories.length ? [SubEpicViewModel.of(epic, { parent: epic.node, order: 0 }, epic.stories)] : []
return new EpicViewModel(epic, place, [...own, ...epic.epics.map((subEpic, index) => SubEpicViewModel.of(subEpic, under(index)))])

const under = placesUnder(storyMap.node)
const scope = new Set(storyMap.scope)
const epics = storyMap.epics.map((epic, index) => EpicViewModel.of(epic, under(index)))
const shown = scoped && scope.size ? epics.flatMap(epic => epic.within(scope) ?? []) : epics
return new StoryMapViewModel(storyMap, shown, storyMap.increments.map((increment, index) => IncrementViewModel.of(increment, under(index))))

const stories = this.epics.flatMap(epic => epic.sub_epics.flatMap(sub => sub.stories))
const scenarios = stories.flatMap(story => story.scenarios)
return [...this.epics, ...this.epics.flatMap(epic => epic.sub_epics), ...stories, ...scenarios, ...this.increments]

for self.number, self.raw in enumerate(lines, start=1):
    if self.raw.strip():
        self._read_line()
return self.story_map

heading = HEADING_PATTERN.match(self.raw)
if heading is None:
    return False
depth, name = len(heading.group(1)), heading.group(2).strip()
if any(name.lower().startswith(prefix) for prefix in _DOC_TITLE_PREFIXES):
    return True
if name.lower() in _NON_STORY_SECTIONS:
    self.ignored_heading_depth = depth
elif name.lower().startswith("story:"):
    self._named_story(name.split(":", 1)[1].strip() or name)
elif self._is_epic_heading(depth):
    self.epic_heading_depth = depth if self.epic_heading_depth is None else self.epic_heading_depth
    self._open_epic(name)
    self.story = None
elif self.epic is not None:
    self._accept_nested_heading(name, depth)
return True

bullet = _BULLET_PATTERN.match(self.raw)
if bullet is None:
    return False
indent, text = len(bullet.group(1)) // 2, bullet.group(2).strip()
if indent == 0 and self.epic is not None:
    self._named_story(text)
elif indent >= 1 and self.story is not None:
    self._listed_scenario(text)
return True

for self.number, self.raw in enumerate(lines, start=1):
    self._read_line()
for node in [self.story_map, *self.story_map.every_epic(), *self.story_map.every_story()]:
    node.outline.read_from(node)
return self.story_map

under = self.described
if (self._accept_epic() or self._accept_story()) and self.described is not under:
    self.described.outline = OutlineLines(self.raw)
elif self.described is under and not self._accept_estimate():
    self.described.outline.lines.append(self.raw)
    self._accept_evidence()

match = _OUTLINE_EPIC_PATTERN.match(self.raw)
if match is None:
    return False
depth, name = _outline_depth(match), strip_backticks(unlink(match.group("name")))
self.story = None
if depth <= 0:
    self._open_epic(name)
elif self.epic is not None:
    self._open_sub_epic(name, depth)
return True

match = _OUTLINE_STORY_PATTERN.match(self.raw)
if match is None or self.epic is None:
    return False
parent_depth = _outline_depth(match) - 1
if match.group("marks") or parent_depth <= 0:
    while len(self.sub_epics) > max(parent_depth, 0):
        self.sub_epics.pop()
actor, name = self._actor_and_name(match.group("name"))
self.story = self._story(name, self.sub_epics[-1] if self.sub_epics else self.epic, StoryType.from_mark(match.group("kind")))
if actor:
    self.story.actors = [actor]
return True

if self.story is None:
    return
evidence = self.story.evidence
for label in (with_evidence or ending for with_evidence, ending in _EVIDENCE_LABEL.findall(self.raw)):
    if label.lower() not in evidence:
        evidence.append(label.lower())

raw_text = unlink(raw_text)
if "-->" not in raw_text:
    return "", strip_backticks(raw_text)
actor, name = raw_text.split("-->", 1)
return strip_backticks(actor), strip_backticks(name)

if self.description_text == self.lines.description:
    return self.lines.described
return described(self.description_text) or [""]

delivered = {id(story) for story in self.stories}
written = [_bullet_as_read(*bullet) for bullet in self.lines.bullets if bullet[1] is None or id(bullet[1]) in delivered]
shown = {id(story) for _, story, _ in self.lines.bullets}
return written + [_bullet(story) for story in self.stories if id(story) not in shown]

body: List[str] = []
for index, increment in enumerate(increments):
    if increment.lines is None and body[-1:] not in ([], [""]):
        body.append("")
    body.extend(increment.thin_slice_lines(self.first_number + index))
return "\n".join([*self.above, *body]).rstrip("\n") + "\n"

found = StoryMapFiles(folder).thin_slicing()
if found is None:
    return ThinSlice(Path(folder) / "thin-slice.md", list(_NEW_THIN_SLICE))
text = found.read_text(encoding="utf-8")
reading = _ThinSliceReading(story_map, path_from(Path(project).resolve(), found))
for increment in reading.read(text.splitlines()):
    story_map.append_increment(increment)
return ThinSlice(found, reading.above, reading.first_number, text)

for number, raw in enumerate(lines, start=1):
    heading = _INCREMENT_H3.match(raw.strip())
    if heading is not None:
        self._open(raw, heading, number)
    elif self.increments:
        self._read_line(raw, self.increments[-1])
    else:
        self.above.append(raw)
self._close()
return self.increments

lines = increment.lines
bullet = _BULLET.match(raw) if self.in_stories else None
if bullet is not None:
    self._read_bullet(raw, bullet.group(1), increment)
elif lines.bullets:
    self.in_stories = False
    lines.below.append(raw)
elif self.in_stories and not raw.strip():
    lines.above.append(raw)
else:
    self.in_stories = _read_field(raw.strip(), increment)
    (lines.above if self.in_stories or lines.above else lines.described).append(raw)

if match := _KV_OUTCOME.match(stripped):
    increment.outcome = strip_markup(match.group(1))
elif match := _KV_SLICING.match(stripped):
    increment.slicing_notes = strip_markup(match.group(1))
elif match := _KV_DECISION.match(stripped):
    increment.decision_prompt = strip_markup(match.group(1))
return bool(_KV_STORIES.match(stripped))

if not token:
    return "unknown-noun"
# A word the verb list lacks is not evidence of a noun ("Carry Plan ..."); only the classes listed are flagged.
return next((label for label, holds in _OPENINGS if holds(token)), "unlisted")

relative = str(getattr(source, "file", "") or "") if source is not None else ""
name = relative.replace("\\", "/").rsplit("/", 1)[-1]
return name, _camel_case(name)

if not name or name == "." or _KEBAB_FILE.match(name):
    return False
return bool(_CAMEL_FILE.search(name) or re.search(r"[A-Z]", name.split(".")[0]))

own = self._rendered(self.own_format)
if not self._reads_back(own):
    raise StoryMapEditRefused(self._story_map, "save", f"{self.file} would not keep the edit: {self.own_format} does not read it back")
written = [self._write(self.own_format, self._path)]
if self._story_map.slicing is not None:
    written += self._story_map.slicing.write(self._story_map.increments)
for chosen in self.fidelity.session_output.chosen_formats:
    if Format(chosen) != self.own_format:
        written.append(self._write(Format(chosen), self._path.with_suffix(Format(chosen).extension)))
self._session.graph.refresh([str(path) for path in written])
self._read_back = own
return written

model = self._stories.formats.parse(self.own_format, text)
again = self._stories.formats.render(RenderRequest(self.own_format, model, previous=text))["content"]
return _nodes_held(model) == _nodes_held(self._story_map) and again.strip() == text.strip()

self._copy = copy
self._increments = list(original.increments)
self._copies = {id(story): copied for story, copied in zip(original.every_story(), copy.every_story())}

if self._read_back.strip() == self._path.read_text(encoding="utf-8").strip():
    return ""
return f"saving would rewrite {self.file}, a {self.fidelity.name} file, beyond the edit: its text is not laid out as {self.own_format} writes a story map"
